CREATE TABLE IF NOT EXISTS communities ( id CHAR(26) PRIMARY KEY, owner_id CHAR(26) NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(2000), category VARCHAR(100), avatar_url VARCHAR(2048), base_type ENUM('city_based','online_only'), country VARCHAR(100), state VARCHAR(100), city VARCHAR(100), latitude DOUBLE, longitude DOUBLE, discovery_radius_km INT, interests JSON, event_id CHAR(26), visibility ENUM('public','private') DEFAULT 'public', show_in_search TINYINT(1) DEFAULT 1, allow_recommendations TINYINT(1) DEFAULT 1, show_on_host_profile TINYINT(1) DEFAULT 1, join_policy ENUM('open','approval','invite_only') DEFAULT 'open', allow_member_invites TINYINT(1) DEFAULT 1, can_create_posts TINYINT(1) DEFAULT 1, can_comment TINYINT(1) DEFAULT 1, can_create_polls TINYINT(1) DEFAULT 0, can_create_events TINYINT(1) DEFAULT 0, can_submit_event_request TINYINT(1) DEFAULT 1, can_create_groups TINYINT(1) DEFAULT 0, can_invite_members TINYINT(1) DEFAULT 1, can_view_directory TINYINT(1) DEFAULT 1, require_approval_before_publishing TINYINT(1) DEFAULT 0, allow_external_links TINYINT(1) DEFAULT 1, auto_spam_detection TINYINT(1) DEFAULT 1, hold_flagged_for_review TINYINT(1) DEFAULT 1, admins_can_moderate TINYINT(1) DEFAULT 1, moderators_can_moderate TINYINT(1) DEFAULT 0, require_post_approval TINYINT(1) DEFAULT 0, require_member_approval TINYINT(1) DEFAULT 0, require_approval TINYINT(1) DEFAULT 0, admins_can_approve TINYINT(1) DEFAULT 1, guidelines VARCHAR(4000), prohibited_content JSON, community_activity TINYINT(1) DEFAULT 1, community_events TINYINT(1) DEFAULT 1, created_at CHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS `groups` ( id CHAR(26) PRIMARY KEY, community_id CHAR(26) NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(500), join_policy ENUM('open','approval','invite_only') DEFAULT 'open', created_at CHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS memberships ( id CHAR(26) PRIMARY KEY, community_id CHAR(26) NOT NULL, group_id CHAR(26), user_id CHAR(26) NOT NULL, role ENUM('owner','admin','moderator','member') DEFAULT 'member', status ENUM('member','pending','blocked') DEFAULT 'member', created_at CHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS join_requests ( id CHAR(26) PRIMARY KEY, community_id CHAR(26) NOT NULL, group_id CHAR(26), user_id CHAR(26) NOT NULL, status ENUM('pending','approved','denied') DEFAULT 'pending', note VARCHAR(500), created_at CHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS messages ( id CHAR(26) PRIMARY KEY, group_id CHAR(26) NOT NULL, author_id CHAR(26) NOT NULL, type ENUM('text','image','video','file','announcement') NOT NULL DEFAULT 'text', text VARCHAR(2000), media_url VARCHAR(2048), title VARCHAR(200), created_at CHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS posts ( id CHAR(26) PRIMARY KEY, community_id CHAR(26) NOT NULL, author_id CHAR(26) NOT NULL, type ENUM('post','announcement') DEFAULT 'post', text VARCHAR(5000) NOT NULL, media_urls JSON, status ENUM('published','held','removed') DEFAULT 'published', created_at CHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS likes ( id CHAR(26) PRIMARY KEY, post_id CHAR(26) NOT NULL, user_id CHAR(26) NOT NULL, created_at CHAR(24) NOT NULL, UNIQUE uq_like (post_id, user_id));
CREATE TABLE IF NOT EXISTS comments ( id CHAR(26) PRIMARY KEY, post_id CHAR(26) NOT NULL, author_id CHAR(26) NOT NULL, text VARCHAR(1000) NOT NULL, created_at CHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS reports ( id CHAR(26) PRIMARY KEY, community_id CHAR(26), target_type ENUM('message','member','event','community') NOT NULL, target_id CHAR(26) NOT NULL, reason VARCHAR(500) NOT NULL, reporter_id CHAR(26) NOT NULL, status ENUM('open','actioned','dismissed') DEFAULT 'open', created_at CHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS blocks ( id CHAR(26) PRIMARY KEY, community_id CHAR(26) NOT NULL, user_id CHAR(26) NOT NULL, created_at CHAR(24) NOT NULL, UNIQUE uq_block (community_id, user_id));
CREATE TABLE IF NOT EXISTS mutes ( id CHAR(26) PRIMARY KEY, community_id CHAR(26) NOT NULL, user_id CHAR(26) NOT NULL, created_at CHAR(24) NOT NULL, UNIQUE uq_mute (community_id, user_id));
CREATE TABLE IF NOT EXISTS user_blocked_communities ( id CHAR(26) PRIMARY KEY, user_id CHAR(26) NOT NULL, community_id CHAR(26) NOT NULL, created_at CHAR(24) NOT NULL, UNIQUE uq_ublock (user_id, community_id));
CREATE TABLE IF NOT EXISTS community_events ( community_id CHAR(26) NOT NULL, event_id CHAR(26) NOT NULL, PRIMARY KEY (community_id, event_id));
CREATE TABLE IF NOT EXISTS exports ( id CHAR(26) PRIMARY KEY, community_id CHAR(26) NOT NULL, type ENUM('members','content','events','full') NOT NULL, status ENUM('queued','ready','failed') DEFAULT 'queued', download_url VARCHAR(2048), created_at CHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS uploads ( id CHAR(26) PRIMARY KEY, user_id CHAR(26) NOT NULL, purpose ENUM('avatar','event_cover','community_media','message_media') NOT NULL, content_type VARCHAR(50) NOT NULL, media_url VARCHAR(2048) NOT NULL, created_at CHAR(24) NOT NULL);
